## IAM Configuration for vpc_peering_overexposed scenario

# Initial user with limited permissions for the assumed breach scenario
resource "aws_iam_user" "initial_user" {
  name = "${var.initial_username}-${var.cgid}"
}

resource "aws_iam_user_policy" "initial_user_policy" {
  name = "initial-user-policy-${var.cgid}"
  user = aws_iam_user.initial_user.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeVpcs",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeRouteTables",
          "ec2:DescribeVpcPeeringConnections"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_access_key" "initial_user_key" {
  user = aws_iam_user.initial_user.name
}

# Role for Dev EC2 - Intentionally over-permissioned
resource "aws_iam_role" "dev_ec2_role" {
  name = "dev-ec2-role-${var.cgid}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })

  tags = {
    Name = "dev-ec2-role-${var.cgid}"
  }
}

# Policy for Dev EC2 with excessive permissions for lateral movement
resource "aws_iam_role_policy" "dev_ec2_policy" {
  name = "dev-ec2-policy-${var.cgid}"
  role = aws_iam_role.dev_ec2_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeVpcs",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeRouteTables",
          "ec2:DescribeVpcPeeringConnections",
          "ssm:StartSession",
          "ssm:DescribeInstanceInformation",
          "ssm:GetConnectionStatus",
          "rds:DescribeDBInstances"
        ]
        Resource = "*"
      }
    ]
  })
}

# Instance profile for Dev EC2
resource "aws_iam_instance_profile" "dev_ec2_profile" {
  name = "dev-ec2-profile-${var.cgid}"
  role = aws_iam_role.dev_ec2_role.name
}

# Role for Prod EC2 - Minimal permissions
resource "aws_iam_role" "prod_ec2_role" {
  name = "prod-ec2-role-${var.cgid}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })

  tags = {
    Name = "prod-ec2-role-${var.cgid}"
  }
}

# Policy for Prod EC2 with minimal permissions
resource "aws_iam_role_policy" "prod_ec2_policy" {
  name = "prod-ec2-policy-${var.cgid}"
  role = aws_iam_role.prod_ec2_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ssm:UpdateInstanceInformation",
          "ssm:ListInstanceAssociations"
        ]
        Resource = "*"
      }
    ]
  })
}

# Instance profile for Prod EC2
resource "aws_iam_instance_profile" "prod_ec2_profile" {
  name = "prod-ec2-profile-${var.cgid}"
  role = aws_iam_role.prod_ec2_role.name
}

# SSM permissions to allow Session Manager access
resource "aws_iam_policy" "ssm_policy" {
  name        = "ssm-policy-${var.cgid}"
  description = "Allow SSM Session Manager access"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssm:UpdateInstanceInformation",
          "ssm:ListInstanceAssociations",
          "ssm:ListAssociations",
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel",
          "ec2messages:AcknowledgeMessage",
          "ec2messages:GetMessages",
          "ec2messages:SendReply",
          "ec2messages:GetEndpoint",
          "ssm:StartSession",
          "ssm:TerminateSession",
          "ssm:DescribeSessions"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "prod_ec2_ssm_policy" {
  role       = aws_iam_role.prod_ec2_role.name
  policy_arn = aws_iam_policy.ssm_policy.arn
}

resource "aws_iam_role_policy_attachment" "dev_ec2_ssm_policy" {
  role       = aws_iam_role.dev_ec2_role.name
  policy_arn = aws_iam_policy.ssm_policy.arn
}

## Output Configuration for vpc_peering_overexposed scenario

# Initial access credentials
output "initial_access_key" {
  description = "The AWS access key for the initial user"
  value       = aws_iam_access_key.initial_user_key.id
}

output "initial_secret_key" {
  description = "The AWS secret key for the initial user"
  value       = aws_iam_access_key.initial_user_key.secret
  sensitive   = true
}

# Dev EC2 information
output "dev_ec2_public_ip" {
  description = "Public IP address of the Dev EC2 instance"
  value       = aws_instance.dev_ec2.public_ip
  sensitive   = true
}

output "dev_ec2_instance_id" {
  description = "Instance ID of the Dev EC2 instance"
  value       = aws_instance.dev_ec2.id
}

output "dev_ec2_ssh_key" {
  description = "Path to the SSH private key for the Dev EC2 instance"
  value       = "The SSH key is saved as cloudgoat.pem in the scenario directory"
}

# VPC information
output "dev_vpc_id" {
  description = "ID of the Dev VPC"
  value       = aws_vpc.dev_vpc.id
}

# Scenario instructions
output "scenario_instructions" {
  description = "Instructions to start the scenario"
  value       = <<-EOT
    ========================[ vpc_peering_overexposed ]========================

    You have successfully deployed the vpc_peering_overexposed scenario!

    Initial Access:
    - AWS Access Key: ${aws_iam_access_key.initial_user_key.id}
    - AWS Secret Key: ${aws_iam_access_key.initial_user_key.secret}

    SSH Access:
    - SSH Key: cloudgoat.pem (in the scenario directory)

    Your goal is to:
    1. Enumerate the AWS environment
    2. Exploit EC2 metadata service to gain higher privileges
    3. Identify and exploit VPC peering misconfigurations
    4. Move laterally to production environment 
    5. Access sensitive customer data

    Start by configuring the AWS CLI with the provided credentials:


    Good luck!
    ========================================================================
  EOT
  sensitive   = true
}

## AWS Provider Configuration for vpc_peering_overexposed scenario
## Configure required Terraform and provider versions.

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.74.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.4.0"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region

  # This configures default tags for all resources
  default_tags {
    tags = {
      Name     = "vpc-peering-${var.cgid}"
      Stack    = var.stack-name
      Scenario = var.scenario-name
    }
  }
}

## Variables for vpc_peering_overexposed scenario

variable "profile" {
  description = "The AWS profile to use when deploying resources"
  type        = string
}

variable "region" {
  description = "The AWS region to deploy resources into"
  default     = "us-east-1"
  type        = string

  validation {
    condition     = can(regex("^(us-east-1|us-west-1|us-west-2|eu-west-1|eu-central-1)$", var.region))
    error_message = "The region must be a valid AWS region where all required services are available."
  }
}

variable "cgid" {
  description = "CGID variable for unique naming between scenarios"
  type        = string

  validation {
    condition     = can(regex("^[a-z0-9]{6,20}$", var.cgid))
    error_message = "The cgid must be 6-20 lowercase alphanumeric characters."
  }
}

variable "cg_whitelist" {
  description = "User's public IP address(es) for restricting access to resources"
  type        = list(string)
}

# VPC and networking variables
variable "dev_vpc_cidr" {
  description = "CIDR block for the Dev VPC"
  default     = "10.10.0.0/16"
  type        = string
}

variable "prod_vpc_cidr" {
  description = "CIDR block for the Prod VPC"
  default     = "10.20.0.0/16"
  type        = string
}

variable "dev_subnet_cidr" {
  description = "CIDR block for the Dev subnet"
  default     = "10.10.10.0/24"
  type        = string
}

variable "prod_subnet_cidr" {
  description = "CIDR block for the Prod subnet"
  default     = "10.20.10.0/24"
  type        = string
}

variable "prod_db_subnet_cidr" {
  description = "CIDR block for the Prod DB subnet"
  default     = "10.20.20.0/24"
  type        = string
}

# EC2 variables
variable "ec2_instance_type" {
  description = "Instance type for EC2 instances"
  default     = "t3.micro"
  type        = string

  validation {
    condition     = contains(["t3.micro", "t3.small", "t4g.micro"], var.ec2_instance_type)
    error_message = "The instance type must be small to stay within free tier limits."
  }
}

# Database variables
variable "db_instance_class" {
  description = "Instance class for RDS MySQL"
  default     = "db.t3.micro"
  type        = string

  validation {
    condition     = contains(["db.t4g.micro", "db.t3.micro"], var.db_instance_class)
    error_message = "The database instance class must be small to stay within free tier limits."
  }
}

variable "db_name" {
  description = "Name of the MySQL database"
  default     = "customerdb"
  type        = string
}

variable "db_username" {
  description = "Username for MySQL database"
  default     = "admin"
  type        = string
  sensitive   = true
}

variable "db_password" {
  description = "Password for MySQL database (auto-generated if not provided)"
  type        = string
  default     = "Sup3rSecr3tPassw0rd1"
  sensitive   = true

  validation {
    condition     = length(var.db_password) >= 8
    error_message = "The database password must be at least 8 characters long."
  }
}

# User credentials
variable "initial_username" {
  description = "Username for the initial IAM user"
  default     = "cguser"
  type        = string
}

# Stack naming variables required by CloudGoat
variable "stack-name" {
  description = "Name of the stack"
  default     = "CloudGoat"
  type        = string
}

variable "scenario-name" {
  description = "Name of the scenario being deployed"
  default     = "vpc_peering_overexposed"
  type        = string
}

## VPC and Networking Configuration for vpc_peering_overexposed scenario

# Dev VPC with public subnet
resource "aws_vpc" "dev_vpc" {
  cidr_block           = var.dev_vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name        = "dev-vpc-${var.cgid}"
    Environment = "Development"
  }
}

resource "aws_internet_gateway" "dev_igw" {
  vpc_id = aws_vpc.dev_vpc.id

  tags = {
    Name = "dev-igw-${var.cgid}"
  }
}

resource "aws_subnet" "dev_subnet" {
  vpc_id                  = aws_vpc.dev_vpc.id
  cidr_block              = var.dev_subnet_cidr
  availability_zone       = "${var.region}a"
  map_public_ip_on_launch = true

  tags = {
    Name        = "dev-subnet-${var.cgid}"
    Environment = "Development"
  }
}

resource "aws_route_table" "dev_route_table" {
  vpc_id = aws_vpc.dev_vpc.id

  tags = {
    Name = "dev-route-table-${var.cgid}"
  }
}

resource "aws_route" "dev_internet_route" {
  route_table_id         = aws_route_table.dev_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.dev_igw.id
}

resource "aws_route_table_association" "dev_route_association" {
  subnet_id      = aws_subnet.dev_subnet.id
  route_table_id = aws_route_table.dev_route_table.id
}

# Prod VPC with private subnet
resource "aws_vpc" "prod_vpc" {
  cidr_block           = var.prod_vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name        = "prod-vpc-${var.cgid}"
    Environment = "Production"
  }
}

resource "aws_subnet" "prod_subnet" {
  vpc_id                  = aws_vpc.prod_vpc.id
  cidr_block              = var.prod_subnet_cidr
  availability_zone       = "${var.region}a"
  map_public_ip_on_launch = false # Private subnet

  tags = {
    Name        = "prod-subnet-${var.cgid}"
    Environment = "Production"
  }
}

resource "aws_subnet" "prod_db_subnet" {
  vpc_id                  = aws_vpc.prod_vpc.id
  cidr_block              = var.prod_db_subnet_cidr
  availability_zone       = "${var.region}b"
  map_public_ip_on_launch = false # Private subnet

  tags = {
    Name        = "prod-db-subnet-${var.cgid}"
    Environment = "Production"
  }
}

resource "aws_route_table" "prod_route_table" {
  vpc_id = aws_vpc.prod_vpc.id

  tags = {
    Name = "prod-route-table-${var.cgid}"
  }
}

resource "aws_route_table_association" "prod_route_association" {
  subnet_id      = aws_subnet.prod_subnet.id
  route_table_id = aws_route_table.prod_route_table.id
}

resource "aws_route_table_association" "prod_db_route_association" {
  subnet_id      = aws_subnet.prod_db_subnet.id
  route_table_id = aws_route_table.prod_route_table.id
}

# VPC Peering Connection - Intentionally misconfigured to allow all traffic between VPCs
resource "aws_vpc_peering_connection" "dev_to_prod" {
  vpc_id      = aws_vpc.dev_vpc.id
  peer_vpc_id = aws_vpc.prod_vpc.id
  auto_accept = true

  tags = {
    Name = "dev-to-prod-peering-${var.cgid}"
  }
}

# Misconfigured route tables to allow overly permissive access between VPCs
resource "aws_route" "dev_to_prod_route" {
  route_table_id            = aws_route_table.dev_route_table.id
  destination_cidr_block    = var.prod_vpc_cidr
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_to_prod.id
}

resource "aws_route" "prod_to_dev_route" {
  route_table_id            = aws_route_table.prod_route_table.id
  destination_cidr_block    = var.dev_vpc_cidr
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_to_prod.id
}

# Security Groups
resource "aws_security_group" "dev_sg" {
  name        = "dev-security-group-${var.cgid}"
  description = "Security group for Dev EC2 instance"
  vpc_id      = aws_vpc.dev_vpc.id

  # Allow SSH from whitelisted IPs
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.cg_whitelist
  }

  # Allow all outbound traffic
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "dev-sg-${var.cgid}"
  }
}

resource "aws_security_group" "prod_sg" {
  name        = "prod-security-group-${var.cgid}"
  description = "Security group for Prod EC2 instance"
  vpc_id      = aws_vpc.prod_vpc.id

  # Misconfigured to allow SSH from Dev VPC
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.dev_vpc_cidr]
  }

  # Allow SSM connections
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.dev_vpc_cidr]
  }

  # Allow all outbound traffic
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "prod-sg-${var.cgid}"
  }
}

resource "aws_security_group" "db_sg" {
  name        = "db-security-group-${var.cgid}"
  description = "Security group for RDS MySQL instance"
  vpc_id      = aws_vpc.prod_vpc.id

  # Allow MySQL connections only from Prod subnet
  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [var.prod_subnet_cidr]
  }

  # Allow all outbound traffic
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "db-sg-${var.cgid}"
  }
}

# VPC Endpoints for SSM in the Production VPC
resource "aws_security_group" "ssm_endpoint_sg" {
  name        = "ssm-endpoint-sg-${var.cgid}"
  description = "Security group for SSM VPC endpoints"
  vpc_id      = aws_vpc.prod_vpc.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.prod_subnet_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ssm-endpoint-sg-${var.cgid}"
  }
}

# SSM Endpoints - Required for SSM to work in a private subnet
resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = aws_vpc.prod_vpc.id
  service_name        = "com.amazonaws.${var.region}.ssm"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.prod_subnet.id]
  security_group_ids  = [aws_security_group.ssm_endpoint_sg.id]

  tags = {
    Name = "ssm-endpoint-${var.cgid}"
  }
}

resource "aws_vpc_endpoint" "ssm_messages" {
  vpc_id              = aws_vpc.prod_vpc.id
  service_name        = "com.amazonaws.${var.region}.ssmmessages"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.prod_subnet.id]
  security_group_ids  = [aws_security_group.ssm_endpoint_sg.id]

  tags = {
    Name = "ssm-messages-endpoint-${var.cgid}"
  }
}

resource "aws_vpc_endpoint" "ec2_messages" {
  vpc_id              = aws_vpc.prod_vpc.id
  service_name        = "com.amazonaws.${var.region}.ec2messages"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.prod_subnet.id]
  security_group_ids  = [aws_security_group.ssm_endpoint_sg.id]

  tags = {
    Name = "ec2-messages-endpoint-${var.cgid}"
  }
}

# S3 Gateway Endpoint for the Prod VPC to allow package installation
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.prod_vpc.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.prod_route_table.id]

  tags = {
    Name = "s3-endpoint-${var.cgid}"
  }
}
